/* Reusable dropdowns: inventory collections and non-inventory record lists. */
function ensureLists(){ensureItemState();if(state.dataSources&&!state.dataLists)state.dataLists=state.dataSources;state.dataLists??=[];state.dataSources=state.dataLists;for(const c of state.itemCategories.filter(c=>!c.parentId)){const existing=state.dataLists.find(s=>s.kind==='items'&&s.categoryId===c.id);if(existing){existing.name=c.name;existing.owner=c.module;}else state.dataLists.push({id:'source-'+c.id,name:c.name,owner:c.module,kind:'items',categoryId:c.id,shares:[],revision:1});}if(!state.listsSeeded){state.dataLists.push({id:'source-vendors',name:'Approved vendors',owner:'Procurement',kind:'records',shares:['Sales','Feed'],revision:1,records:[{id:'vendor-north',name:'North supplier · demo',active:true},{id:'vendor-local',name:'Local supplier · demo',active:true}]},{id:'source-pens',name:'Pens & locations',owner:'Counts',kind:'records',shares:['Weighing','Feed','Health','Procurement'],revision:1,records:[{id:'pen-cbe-1',name:'CBE · Pen 1',active:true},{id:'pen-cbe-2',name:'CBE · Pen 2',active:true}]});state.listsSeeded=true;}return state.dataLists;}
function listById(id){const lists=ensureLists();return lists.find(s=>s.id===id)||lists.find(s=>id&&s.id===String(id).replace(/^source-/,'list-'))||lists.find(s=>id&&s.id===String(id).replace(/^list-/,'source-'))||lists.find(s=>id&&s.categoryId&&String(id).startsWith('source-'))}
function listMembers(s){return s.kind==='items'?state.items.filter(i=>i.module===s.owner&&i.categoryId===s.categoryId):(s.records||[]).map(i=>({...i,module:s.owner,unit:'record',purpose:s.name,revision:s.revision}));}
function listOptions(s,m=current){if(!s)return [];return listMembers(s).filter(i=>i.active&&((s.owner===m&&m!=='Common')||s.shares.includes(m)||(s.kind==='items'&&i.shares.includes(m))||(s.kind==='items'&&typeof genericItemAccess==='function'&&genericItemAccess(i).some(a=>a.module===m))));}
function visibleLists(m=current){return ensureLists().filter(s=>s.owner===m||s.shares.includes(m)||listOptions(s,m).length);}
const listsOldAvailable=availableItems;
availableItems=function(m){ensureLists();return state.items.filter(i=>i.active&&(i.module===m||i.shares.includes(m)||state.dataLists.some(s=>s.kind==='items'&&s.owner===i.module&&s.categoryId===i.categoryId&&s.shares.includes(m))));};
const listsOldCatalogue=nodeCatalogue;
nodeCatalogue=function(n,m=current){const id=n.catalogueListId||n.catalogueSourceId;return id?listOptions(listById(id),m):listsOldCatalogue(n,m);};
function listDependencies(id,m){return allWorkflowDrafts().filter(([mod,s])=>(!m||mod===m)&&s.nodes.some(n=>n.catalogueListId===id||(n.relistListId||n.resourceSourceId)===id));}
function toggleListAccess(id,m,on){if(!canEdit())return;const s=listById(id);if(!s||m===s.owner)return;if(!on){modal('Review list access',`<p>Remove whole-list access to ${esc(s.name)} for ${esc(m)}?</p><p>${listDependencies(id,m).length} workflow drafts reference this list. Published snapshots stay unchanged. Items shared individually remain available.</p><button class="danger" onclick="applyListAccess('${id}','${m}',false);closeModal();render()">Remove list access</button><button onclick="closeModal();render()">Keep access</button>`);return;}applyListAccess(id,m,true);}
function applyListAccess(id,m,on){if(!canEdit())return;const s=listById(id);if(!s||s.owner===m)return;s.shares=s.shares.filter(x=>x!==m);if(on)s.shares.push(m);s.revision++;record('Updated list access: '+s.name+' / '+m);render();}
let listDirectoryOwner='',listDirectoryKind='';const listPickerFilters={};
function showLists(){const list=ensureLists().filter(s=>(!listDirectoryOwner||s.owner===listDirectoryOwner)&&(!listDirectoryKind||s.kind===listDirectoryKind));$('#content').innerHTML=`<div class="heading"><div><h2>Reusable dropdown lists</h2><p>Choose a reusable list for dropdown questions or reference actions.</p></div><button class="primary" onclick="listModal()" ${canEdit()?'':'disabled'}>+ New dropdown list</button></div><div class="notice">Sharing a list makes its active records available to selected work areas. Published workflows keep the saved list version.</div><div class="inputrow list-directory-filters"><label class="field"><span>Business area</span><select aria-label="Dropdown list business area" onchange="listDirectoryOwner=this.value;showLists()"><option value="">All areas</option>${modules.map(m=>`<option ${listDirectoryOwner===m?'selected':''}>${m}</option>`).join('')}</select></label><label class="field"><span>List type</span><select aria-label="Dropdown list type" onchange="listDirectoryKind=this.value;showLists()"><option value="">All lists</option><option value="items" ${listDirectoryKind==='items'?'selected':''}>Item groups</option><option value="records" ${listDirectoryKind==='records'?'selected':''}>Record lists</option></select></label></div><div class="lists-grid">${list.map(s=>`<section class="card list-card" role="button" tabindex="0" onclick="listModal('${s.id}')" onkeydown="if(event.key==='Enter'||event.key===' '){event.preventDefault();listModal('${s.id}')}"><div class="cardheader"><div><span class="eyebrow">${esc(s.owner)} · ${s.kind==='items'?'ITEM GROUP':'RECORD LIST'}</span><h2>${esc(s.name)}</h2></div><span class="badge blue">${listMembers(s).filter(i=>i.active).length} active</span></div><p>${s.kind==='items'?'Reusable item group':'Reusable record list'}</p></section>`).join('')}</div>`;}
function listPreview(s,m){const opts=listOptions(s,m);return `<span class="muted">${opts.length} choices visible to ${esc(m)}</span><select aria-label="${esc(s.name)} preview choices"><option>${opts.length?'Choose a record…':'No access or active records'}</option>${opts.map(i=>`<option>${esc(i.name)}</option>`).join('')}</select>`;}
function previewList(id,m){const s=listById(id);$('#preview-'+id).innerHTML=listPreview(s,m);}
function listModal(id){const s=id?listById(id):null;if(s?.kind==='items'){modal(s.name,`<span class="eyebrow">${esc(s.owner)} · ${esc(itemCategoryName(s.categoryId))}</span>${listMembers(s).map(i=>`<div class="linkline"><span>${esc(i.name)}</span><span class="badge">${i.active?'Active':'Archived'}</span></div>`).join('')}`);return;}const dis=canEdit()?'':'disabled';modal(s?'Record list':'New record list',`<label class="field"><span>List name</span><input id="list-name" value="${esc(s?.name||'')}" ${dis}></label><label class="field"><span>Owning module</span><select id="list-owner" ${s?'disabled':dis}>${modules.map(m=>`<option ${m===(s?.owner||'Procurement')?'selected':''}>${m}</option>`).join('')}</select></label><p class="muted">Each line is one dropdown choice.</p>${s?`<div>${s.records.map(r=>`<div class="list-record"><input aria-label="Record ${esc(r.name)}" data-record-id="${r.id}" value="${esc(r.name)}" ${dis}><label class="checkrow"><input type="checkbox" data-record-active="${r.id}" ${r.active?'checked':''} ${dis}>Active</label></div>`).join('')}</div>`:''}<label class="field"><span>${s?'Add records (one per line)':'Records (one per line)'}</span><textarea id="list-new-records" ${dis}></textarea></label><button class="primary" onclick="saveList('${id||''}')" ${dis}>Save list</button>`);}
function saveList(id){if(!canEdit())return;const old=listById(id),name=$('#list-name').value.trim(),owner=old?.owner||$('#list-owner').value;if(!name)return toast('Enter a list name.');if(ensureLists().some(s=>s.id!==id&&s.owner===owner&&s.name.toLowerCase()===name.toLowerCase()))return toast('This owner already has a list with that name.');const records=old?old.records.map(r=>({...r,name:document.querySelector('[data-record-id="'+r.id+'"]').value.trim(),active:document.querySelector('[data-record-active="'+r.id+'"]').checked})):[];for(const n of $('#list-new-records').value.split('\n').map(x=>x.trim()).filter(Boolean))records.push({id:'record-'+crypto.randomUUID(),name:n,active:true});if(!records.length||records.some(r=>!r.name)||new Set(records.map(r=>r.name.toLowerCase())).size!==records.length)return toast('Add unique, non-empty record names.');const next={id:old?.id||id||'source-'+crypto.randomUUID(),name,owner,kind:'records',shares:old?.shares||[],revision:(old?.revision||0)+1,records};if(old&&old.records.some(r=>r.active&&!next.records.find(n=>n.id===r.id)?.active)){window.pendingList=next;window.pendingSource=next;modal('Review archived records',`<p>${listDependencies(id).length} workflow drafts reference this list. Archived choices disappear from new selections; affected decisions and actions must be fixed before publishing. Published snapshots stay unchanged.</p><button class="danger" onclick="commitList(window.pendingList)">Save and archive records</button><button onclick="listModal('${id}')">Discard changes and return</button>`);return;}commitList(next);}
const listOldRender=render;
render=function(){listOldRender();if(current==='Common'&&tab!=='Editor'){const t=$('.tabs');if(t)t.insertAdjacentHTML('afterbegin',`<button class="${tab==='Dropdown lists'?'active':''}" onclick="go('Common','Dropdown lists')">Dropdown lists</button>`);if(tab==='Dropdown lists')showLists();}};
function listSelect(value,attr,kind){const f=listPickerFilters[attr]||{},all=visibleLists(current),list=all.filter(s=>(!kind||s.kind===kind)&&(!f.owner||s.owner===f.owner)&&(!f.kind||s.kind===f.kind));const chosen=all.find(s=>s.id===value);if(chosen&&!list.includes(chosen))list.unshift(chosen);return `<div class="list-picker-filters"><select aria-label="List owner filter" onchange="filterListPicker('${attr}','owner',this.value)"><option value="">All owners</option>${modules.map(m=>`<option ${f.owner===m?'selected':''}>${m}</option>`).join('')}</select><select aria-label="List type filter" onchange="filterListPicker('${attr}','kind',this.value)"><option value="">All lists</option><option value="items" ${f.kind==='items'?'selected':''}>Item groups</option><option value="records" ${f.kind==='records'?'selected':''}>Record lists</option></select></div><select aria-label="${attr==='catalogueListId'?'Dropdown list':'Action list'}" onchange="setNodeList('${attr}',this.value)"><option value="">Choose a shared list…</option>${value&&!all.some(s=>s.id===value)?`<option selected disabled value="${esc(value)}">List access removed</option>`:''}${list.map(s=>`<option value="${s.id}" ${value===s.id?'selected':''}>${esc(s.owner)} · ${esc(s.name)}</option>`).join('')}</select>`;}
function filterListPicker(attr,key,value){listPickerFilters[attr]??={};listPickerFilters[attr][key]=value;inspect();}
function setNodeList(attr,id){if(!canEdit())return;const n=sop().nodes.find(n=>n.id===selected);n[attr]=id;if(attr==='relistListId'||attr==='resourceSourceId'){n.relistId='';n.resourceId='';}persist();drawGraph();inspect();}
const listOldInspect=inspect;
inspect=function(){listOldInspect();const n=sop().nodes.find(n=>n.id===selected),p=$('#inspector');if(!n||!p||!canEdit())return;if(n.type==='question'&&n.answer==='Catalogue'){p.querySelector('.catalogue-config')?.remove();p.insertAdjacentHTML('beforeend',`<div class="catalogue-config"><label class="field"><span>Dropdown list</span>${listSelect(n.catalogueListId,'catalogueListId')}</label><p class="muted">${n.catalogueListId?nodeCatalogue(n).length+' choices available':'Area list until a named dropdown list is selected'}. Ownership and sharing determine what appears.</p><button onclick="go('Common','Dropdown lists')">Dropdown lists</button></div>`);}if(n.type==='action'){const a=p.querySelector('[aria-label="Action type"]');if(a&&!Array.from(a.options).some(o=>o.value==='Use reusable reference'))a.insertAdjacentHTML('beforeend','<option>Use reusable reference</option>');if((n.action==='Use reusable reference'||n.action==='Use shared resource')){a.value=n.action;const src=listById((n.relistListId||n.resourceSourceId)),opts=listOptions(src,current);p.insertAdjacentHTML('beforeend',`<label class="field"><span>Reusable list</span>${listSelect((n.relistListId||n.resourceSourceId),'relistListId')}</label><label class="field"><span>Record / item</span><select aria-label="Record or item" onchange="editNode('relistId',this.value,true)"><option value="">Choose record…</option>${(n.relistId||n.resourceId)&&!opts.some(i=>i.id===(n.relistId||n.resourceId))?'<option selected disabled>Unavailable selection</option>':''}${opts.map(i=>`<option value="${i.id}" ${(n.relistId||n.resourceId)===i.id?'selected':''}>${esc(i.name)}</option>`).join('')}</select></label>`);}}};
const listOldValidate=validateWorkflow;
validateWorkflow=function(s,m=current){const normalized=structuredClone(s);for(const n of normalized.nodes){if(n.catalogueSourceId&&!n.catalogueListId)n.catalogueListId=n.catalogueSourceId;if(n.resourceSourceId&&!n.relistListId)n.relistListId=n.resourceSourceId;if(n.resourceId&&!n.relistId)n.relistId=n.resourceId;if((n.action==='Use reusable reference'||n.action==='Use shared resource'))n.action='Instruction';}const errors=listOldValidate(normalized,m);for(const n of s.nodes){if(n.answer==='Catalogue'&&n.catalogueListId&&!listById(n.catalogueListId))errors.push(n.label+': list no longer exists.');if((n.action==='Use reusable reference'||n.action==='Use shared resource')&&!listOptions(listById((n.relistListId||n.resourceSourceId)),m).some(i=>i.id===(n.relistId||n.resourceId)))errors.push(n.label+': choose an available shared resource.');}return [...new Set(errors)];};
const listOldCompile=compileWorkflow;
compileWorkflow=function(s,m=current,version=s.version||0){const copy=structuredClone(s);for(const n of copy.nodes){if(n.catalogueSourceId&&!n.catalogueListId)n.catalogueListId=n.catalogueSourceId;if(n.resourceSourceId&&!n.relistListId)n.relistListId=n.resourceSourceId;if(n.resourceId&&!n.relistId)n.relistId=n.resourceId;}const d=listOldCompile(copy,m,version);d.lists={};d.sources=d.lists;for(const n of d.nodes){const id=n.catalogueListId||n.catalogueSourceId||(n.relistListId||n.resourceSourceId)||n.resourceSourceId;if(id){const src=listById(id);if(src)d.lists[id]={id:src.id,name:src.name,owner:src.owner,revision:src.revision};}if((n.action==='Use reusable reference'||n.action==='Use shared resource')){const i=listOptions(listById((n.relistListId||n.resourceSourceId)),m).find(i=>i.id===(n.relistId||n.resourceId));if(!i)throw Error(n.label+': choose an available shared resource.');d.items[i.id]=structuredClone(i);n.itemId=i.id;}}return d;};
const listOldGraph=drawGraph;
drawGraph=function(){listOldGraph();for(const n of sop().nodes){if(n.type==='condition'){const q=sop().nodes.find(q=>q.id===(n.source||n.list));if(q?.catalogueListId||q?.catalogueSourceId){const meta=document.querySelector('[data-node="'+n.id+'"] .nmeta'),choice=nodeCatalogue(q).find(i=>i.id===n.value);if(meta)meta.textContent=n.op+' '+(choice?.name||'Unavailable record');}}if((n.action==='Use reusable reference'||n.action==='Use shared resource')){const el=document.querySelector('[data-node="'+n.id+'"] .nmeta'),i=listOptions(listById((n.relistListId||n.resourceSourceId)),current).find(i=>i.id===(n.relistId||n.resourceId));if(el)el.textContent=i?.name||'Choose shared relist';}}};
const listOldItemModal=itemModal;
itemModal=function(id){listOldItemModal(id);const i=itemById(id);if(!i)return;const inherited=ensureLists().filter(s=>s.kind==='items'&&s.owner===i.module&&s.categoryId===i.categoryId&&s.shares.length);if(inherited.length)$('#itemshares').insertAdjacentHTML('beforebegin',`<div class="notice">Additional access through reusable lists: ${inherited.map(s=>esc(s.name)+' → '+s.shares.map(esc).join(', ')).join('; ')}. Change this in Admin authoring tools → Dropdown lists.</div>`);};

function commitList(next){if(!canEdit()||!next)return;const old=listById(next.id);if(old)state.dataLists[state.dataLists.indexOf(old)]=next;else state.dataLists.push(next);window.pendingList=null;record('Saved list '+next.name);closeModal();render();toast('List saved. Published SOP snapshots are unchanged.');}

// Backwards-compatible API names used by older modules.
var ensureSources = ensureLists;
var sourceById = listById;
var sourceMembers = listMembers;
var sourceOptions = listOptions;
var visibleSources = visibleLists;
var sourceDependencies = listDependencies;
var toggleSourceAccess = toggleListAccess;
var applySourceAccess = applyListAccess;
var showSources = showLists;
var sourcePreview = listPreview;
var previewSource = previewList;
var sourceModal = listModal;
var saveSource = saveList;
var commitSource = commitList;
var sourceSelect = listSelect;
var sourcePickerFilters = listPickerFilters;
var sourceDirectoryOwner = listDirectoryOwner;
var sourceDirectoryKind = listDirectoryKind;
showSources=function(){listDirectoryOwner=sourceDirectoryOwner;listDirectoryKind=sourceDirectoryKind;return showLists();};
sourceModal=listModal;saveSource=function(id){if(typeof $==='function'){const sn=$('#source-name'),ln=$('#list-name');if(sn&&ln)ln.value=sn.value;const sr=$('#source-new-records'),lr=$('#list-new-records');if(sr&&lr)lr.value=sr.value;}return saveList(id);};commitSource=function(next){window.pendingList=next;return commitList(next);};
